// ── Builders ────────────────────────────────────────────────────────────────
/**
 * Fit dp builder (Android `DimenFit`). Immutable; values resolve on access.
 *
 * @example
 * const card = fitDp(120).screen(UiModeType.TELEVISION, 200).screen(DpQualifier.SMALL_WIDTH, 600, 180);
 * <View style={{width: card.ftsdp}} />
 */
export class DimenFit extends DimenDpBuilder {
  constructor(initialBaseValue: number) {
    super(S, initialBaseValue);
  }
  /** Resolved on SMALL_WIDTH (dp). */
  get ftsdp(): number {
    return this.dp(DpQualifier.SMALL_WIDTH);
  }
  /** Resolved on SMALL_WIDTH (px). */
  get ftsdpPx(): number {
    return this.px(DpQualifier.SMALL_WIDTH);
  }
  /** Resolved on HEIGHT (dp). */
  get fthdp(): number {
    return this.dp(DpQualifier.HEIGHT);
  }
  /** Resolved on HEIGHT (px). */
  get fthdpPx(): number {
    return this.px(DpQualifier.HEIGHT);
  }
  /** Resolved on WIDTH (dp). */
  get ftwdp(): number {
    return this.dp(DpQualifier.WIDTH);
  }
  /** Resolved on WIDTH (px). */
  get ftwdpPx(): number {
    return this.px(DpQualifier.WIDTH);
  }
}
/** Creates a Fit dp builder (Android `Number.fitDp()`). */
export function fitDp(initialBaseValue: number): DimenFit {
  return new DimenFit(initialBaseValue);
}
/** Fit sp builder (Android `FitSp`). Immutable; values resolve on access. */
export class FitSp extends DimenSpBuilder {
  constructor(initialBaseValue: number) {
    super(S, initialBaseValue);
  }
  /** Font size on SMALL_WIDTH (font scale applied by React Native). */
  get ftssp(): number {
    return this.sp(DpQualifier.SMALL_WIDTH);
  }
  /** Font size on SMALL_WIDTH ignoring the font scale. */
  get ftsem(): number {
    return this.em(DpQualifier.SMALL_WIDTH);
  }
  /** Font size on SMALL_WIDTH in px. */
  get ftsspPx(): number {
    return this.spPx(DpQualifier.SMALL_WIDTH);
  }
  /** Font size on SMALL_WIDTH in px ignoring the font scale. */
  get ftsemPx(): number {
    return this.emPx(DpQualifier.SMALL_WIDTH);
  }
  /** Font size on HEIGHT (font scale applied by React Native). */
  get fthsp(): number {
    return this.sp(DpQualifier.HEIGHT);
  }
  /** Font size on HEIGHT ignoring the font scale. */
  get fthem(): number {
    return this.em(DpQualifier.HEIGHT);
  }
  /** Font size on HEIGHT in px. */
  get fthspPx(): number {
    return this.spPx(DpQualifier.HEIGHT);
  }
  /** Font size on HEIGHT in px ignoring the font scale. */
  get fthemPx(): number {
    return this.emPx(DpQualifier.HEIGHT);
  }
  /** Font size on WIDTH (font scale applied by React Native). */
  get ftwsp(): number {
    return this.sp(DpQualifier.WIDTH);
  }
  /** Font size on WIDTH ignoring the font scale. */
  get ftwem(): number {
    return this.em(DpQualifier.WIDTH);
  }
  /** Font size on WIDTH in px. */
  get ftwspPx(): number {
    return this.spPx(DpQualifier.WIDTH);
  }
  /** Font size on WIDTH in px ignoring the font scale. */
  get ftwemPx(): number {
    return this.emPx(DpQualifier.WIDTH);
  }
}
/** Creates a Fit sp builder (Android `Number.fitSp()`). */
export function fitSp(initialBaseValue: number): FitSp {
  return new FitSp(initialBaseValue);
}

